    "d329-dig.title": "Εβδομαδιαίος έλεγχος: κάνε διαγραφή από τις νέες λίστες που πρόσθεσαν οι εκπτώσεις",
    "d329-dig.why": "Κάθε αγορά συνήθως προσθέτει και ένα newsletter. Καθάρισέ τα πριν εγκατασταθούν.",
