    "d333-dig.title": "Απολογισμός Νοεμβρίου: ποια αλλαγή σε προστάτεψε περισσότερο από τις παρορμητικές αγορές;",
    "d333-dig.why": "Κράτα αυτή την αλλαγή ενεργή όλη τη χρονιά, όχι μόνο στις εκπτώσεις.",
    "d334-dig.title": "Κάνε λίστα με τους βασικούς λογαριασμούς σου και πώς θα μπορούσε ένα έμπιστο πρόσωπο να έχει πρόσβαση σε περίπτωση ανάγκης",
