    /* ===== ΨΗΦΙΑΚΗ ΡΟΗ — ΗΜΕΡΕΣ 335–365 · ΔΕΚΕΜΒΡΙΟΣ · Ψηφιακή κληρονομιά, αντίγραφα & απολογισμός ===== */
    "d335-dig.title": "Όρισε επαφή κληρονομιάς ή διαχείρισης ανενεργού λογαριασμού, όπου το προσφέρουν οι υπηρεσίες σου",
    "d335-dig.why": "Αρκετές μεγάλες υπηρεσίες σου επιτρέπουν να επιλέξεις ποιος θα έχει πρόσβαση ή θα διαχειρίζεται τον λογαριασμό σου μετά από μεγάλη αδράνεια ή θάνατο.",
    "d336-dig.title": "Πες σε ένα έμπιστο πρόσωπο πού φυλάσσονται οι οδηγίες σου για περίπτωση ανάγκης",
