    "d351-dig.why": "Οι νέες εφαρμογές τρυπώνουν όλη τη χρονιά. Ένα ξεκαθάρισμα στο τέλος της κρατά το κινητό σου ελαφρύ.",
    "d352-dig.title": "Καθάρισε το ιστορικό, τα cookies και τα αποθηκευμένα δεδομένα φορμών του browser για ένα φρέσκο ξεκίνημα",
    "d352-dig.why": "Ένας χρόνος αποθηκευμένων δεδομένων περιήγησης είναι κυρίως παρακολούθηση και ακαταστασία. Οι σημαντικοί σου κωδικοί είναι ασφαλείς στον διαχειριστή κωδικών.",
