    "d356-dig.why": "Οι περισσότεροι διαχειριστές επισημαίνουν αδύναμους, επαναλαμβανόμενους ή διαρρεύσαντες κωδικούς. Αν διορθώσεις μερικούς, κλείνεις τη χρονιά με ασφάλεια.",
    "d357-dig.title": "Γράψε τους προσωπικούς σου ψηφιακούς κανόνες για την επόμενη χρονιά",
